import type { Logger } from '../log.js'

/** Locales the statements flow sends to docrender. Statements are issued in these four. */
export const SUPPORTED_LOCALES = ['en', 'de', 'fr', 'es'] as const
export type StatementLocale = (typeof SUPPORTED_LOCALES)[number]

export interface RenderRequest {
  html: string
  locale: StatementLocale
  requestId: string
}

export interface DocrenderClient {
  render(request: RenderRequest): Promise<Uint8Array>
}

export function createDocrenderClient(baseUrl: string, log: Logger): DocrenderClient {
  return {
    async render({ html, locale, requestId }) {
      const response = await fetch(`${baseUrl}/v2/render`, {
        method: 'POST',
        headers: { 'content-type': 'application/json', 'x-request-id': requestId },
        body: JSON.stringify({ html, locale, format: 'pdf' }),
      })
      if (!response.ok) {
        log.warn({ requestId, status: response.status }, 'docrender request failed')
        throw new Error(`docrender responded ${response.status}`)
      }
      return new Uint8Array(await response.arrayBuffer())
    },
  }
}
